def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    def opp_at(i):
        return history[i][1]

    def me_at(i):
        return history[i][0]

    c_opp = sum(1 for i in range(n) if opp_at(i) == 'C')
    d_opp = n - c_opp

    # Quickly identify pure strategies
    if d_opp == 0:
        # Opponent always cooperates. Defect only in a few late rounds to exploit,
        # but avoid triggering retaliation-based peers too early.
        if n >= 85:
            # In endgame, defect most of the time since match resets soon
            if rng.random() < 0.85:
                return 'D'
        elif n >= 60:
            # Occasional probes
            if n % 7 == 0:
                return 'D'
        return 'C'
    if c_opp == 0:
        return 'D'

    last = opp_at(n - 1)
    last2 = opp_at(n - 2) if n >= 2 else 'C'
    last3 = opp_at(n - 3) if n >= 3 else 'C'

    # Streaks
    streak_d = 0
    i = n - 1
    while i >= 0 and opp_at(i) == 'D':
        streak_d += 1
        i -= 1
    streak_c = 0
    i = n - 1
    while i >= 0 and opp_at(i) == 'C':
        streak_c += 1
        i -= 1

    coop_rate = c_opp / n
    remaining = 100 - n

    # Count mutual moves for detecting reciprocity
    mutual_cc = sum(1 for i in range(n) if opp_at(i) == 'C' and me_at(i) == 'C')
    opp_mirror = sum(1 for i in range(1, n) if opp_at(i) == me_at(i - 1))
    mirror_ratio = opp_mirror / (n - 1) if n > 1 else 0.0

    # Endgame: exploit heavily if opponent is generally cooperative
    if remaining <= 3:
        if coop_rate >= 0.55:
            return 'D'
        if coop_rate >= 0.4 and rng.random() < 0.5:
            return 'D'
        return 'C'

    if remaining <= 8:
        if coop_rate >= 0.7:
            return 'D'
        if coop_rate >= 0.5:
            return 'D' if rng.random() < 0.6 else 'C'
        if streak_d >= 1:
            return 'D'
        return 'C'

    # Aggressive defector: punish hard, don't forgive often
    if coop_rate <= 0.25:
        return 'D'

    # If opponent is highly retaliatory (mirrors our last move), use TFT-ish behavior
    if n >= 6 and mirror_ratio >= 0.75:
        # Mirror our own last move is their predicted move; we want to
        # choose cooperatively to keep chain going unless they defected recently.
        if last == 'D':
            return 'D'
        # If they have been mostly kind, cooperate
        if coop_rate >= 0.7:
            return 'C'
        if rng.random() < 0.85:
            return 'C'
        return 'D'

    # Recent behavior window
    w = 8 if n >= 8 else n
    rec_def = sum(1 for i in range(n - w, n) if opp_at(i) == 'D')
    rec_coop = w - rec_def

    # Opponent defecting repeatedly: retaliate in kind
    if streak_d >= 2:
        return 'D'

    # Opponent just defected once
    if streak_d == 1:
        # If opponent has been a mostly-kind partner, forgive once in a while
        if coop_rate >= 0.7 and streak_c >= 2:
            if rng.random() < 0.65:
                return 'C'
        if coop_rate >= 0.6 and rng.random() < 0.35:
            return 'C'
        return 'D'

    # Opponent just cooperated (streak_c >= 1)
    # If we defected last round, return to cooperation unless we predict
    # the opponent will keep forgiving and exploit.
    my_last = me_at(n - 1)
    if my_last == 'D':
        # If opponent keeps cooperating after our defections, exploit more
        # but only if they rarely retaliate.
        exploitable = coop_rate >= 0.65 and rec_def <= 1
        if exploitable and remaining > 10 and rng.random() < 0.35:
            return 'D'
        return 'C'

    # Very cooperative opponent: probe occasionally
    if coop_rate >= 0.85:
        # Probes spaced out but also a bit denser late
        if n >= 20 and n % 11 == 0:
            return 'D'
        return 'C'

    if coop_rate >= 0.7:
        if n >= 15 and n % 17 == 0:
            return 'D'
        # If recent defection is isolated, occasionally punish lightly
        if rec_def == 1 and rng.random() < 0.15:
            return 'D'
        return 'C'

    # Moderate cooperation opponent
    if rec_def >= 4:
        return 'D'
    if rec_def >= 2:
        if rng.random() < 0.55:
            return 'D'
        return 'C'

    # Mostly cooperative recent behavior
    if coop_rate >= 0.55 and rng.random() < 0.08 and remaining > 15:
        return 'D'
    return 'C'
